using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class DayNightRepairVerify{static CityDayNightController c;static int phase;static bool old;static float duration;static double started;static string report;static DayNightRepairVerify(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.isCompiling)return;try{if(phase==0){if(!File.Exists("DayNightRepairVerify.request"))return;File.Delete("DayNightRepairVerify.request");c=UnityEngine.Object.FindObjectOfType<CityDayNightController>();old=c.IsNight;duration=c.transitionSeconds;c.Apply(false);if(Shader.GetGlobalFloat("_GangstarNight")!=0)throw new Exception("Day gate failed");c.transitionSeconds=.5f;c.TransitionTo(true);phase=1;started=EditorApplication.timeSinceStartup;return;}if(c.IsTransitioning){if(EditorApplication.timeSinceStartup-started>15)throw new Exception("Real editor transition stalled at "+c.NightBlend);return;}if(phase==1){if(c.NightBlend!=1||Shader.GetGlobalFloat("_GangstarNight")!=1)throw new Exception("Night endpoint failed");report="Actual editor update transition reached NIGHT. ";c.TransitionTo(false);phase=2;started=EditorApplication.timeSinceStartup;return;}if(c.NightBlend!=0||Shader.GetGlobalFloat("_GangstarNight")!=0)throw new Exception("Day endpoint failed");report+="Actual editor update transition reached DAY. ";c.transitionSeconds=40;c.Apply(false);c.TransitionTo(true);c.AdvanceTransition(20);if(Mathf.Abs(c.NightBlend-.5f)>.001)throw new Exception("40-second midpoint failed");c.AdvanceTransition(20);if(c.NightBlend!=1)throw new Exception("40-second endpoint failed");var go=new GameObject("Temporary nearby light test"){hideFlags=HideFlags.HideAndDontSave};var cam=go.AddComponent<Camera>();cam.enabled=false;cam.transform.position=c.streetLightPositions[0]+Vector3.up*2;c.RefreshStreetLights(cam);int enabled=c.streetLights.Count(l=>l&&l.enabled);UnityEngine.Object.DestroyImmediate(go);if(enabled<1||enabled>4)throw new Exception("Nearby light pool failed: "+enabled);c.transitionSeconds=duration;c.Apply(old);EditorUtility.SetDirty(c);EditorSceneManager.MarkSceneDirty(c.gameObject.scene);EditorSceneManager.SaveScene(c.gameObject.scene);File.WriteAllText("FinalEnvironmentRoadReview/DayNightRepairVerify.txt","SUCCESS "+report+"40-second midpoint/end passed; day emission=0, night emission=1. Nearby light pool enabled="+enabled+", max=4. Scene-view light selection and live inspector progress fixed. No extra lights/materials/textures. Original duration="+duration);phase=0;}catch(Exception e){if(c){c.transitionSeconds=duration;c.Apply(old);}phase=0;File.WriteAllText("FinalEnvironmentRoadReview/DayNightRepairVerify.txt",e.ToString());}}}
